    /**
     * Method to retrieve the Record_ via an Record_PrimaryKey.
     * @param 	id Long
     * @return 	Record_
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Record_ handle( FindRecord_Query query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getRecord_Id() );
    }
    
    /**
     * Method to retrieve a collection of all Record_s
     *
     * @param	query	FindAllRecord_Query 
     * @return 	List<Record_> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Record_> handle( FindAllRecord_Query query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindRecord_,
 * but only if the id matches
 *
 * @param		entity	Record_
 */
	protected void emitFindRecord_( Record_ entity ) {
		LOGGER.info("handling emitFindRecord_" );
		
	    queryUpdateEmitter.emit(FindRecord_Query.class,
	                            query -> query.getFilter().getRecord_Id().equals(entity.getRecord_Id()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllRecord_
	 * 
	 * @param		entity	Record_
	 */
	protected void emitFindAllRecord_( Record_ entity ) {
		LOGGER.info("handling emitFindAllRecord_" );
		
	    queryUpdateEmitter.emit(FindAllRecord_Query.class,
	                            query -> true,
	                            entity);
	}

